// @zeus-internal
import type { AgentShape } from "./agent-avatar-paths";
export function createAgentAvatarRenderer(canvas: HTMLCanvasElement): {
  update(options: {
    color: string;
    shape: AgentShape;
    emotion?: number;
    silhouette?: boolean;
  }): boolean;
  setVisible(visible: boolean): void;
  dispose(): void;
};

// @zeus-internal
import * as THREE from "three";
import { SVGLoader } from "three/addons/loaders/SVGLoader.js";
import { AGENT_SHAPE_PATHS, AGENT_SHAPE_LAYOUT, normalizeAgentShape, agentFacePaths } from "./agent-avatar-paths";
import { agentFaceColor, agentSideColor } from "./agent-colors";
import { createAvatarMotion } from "./avatar-motion";
import { subscribeAvatarFrames } from "./avatar-motion-clock";

// One offscreen renderer serves all avatar canvases, including narrow navigation items.
let renderer;
let clients = 0;
let disposeTimer;
const geometries = new Map();
function bodyGeometry(shape) {
  const key = normalizeAgentShape(shape);
  if (geometries.has(key)) return geometries.get(key);
  const data = new SVGLoader().parse(
    `<svg xmlns="http://www.w3.org/2000/svg"><path d="${AGENT_SHAPE_PATHS[key]}"/></svg>`,
  );
  const shapes = data.paths.flatMap((path) => SVGLoader.createShapes(path));
  const geometry = new THREE.ExtrudeGeometry(shapes, {
    depth: 10,
    bevelEnabled: true,
    bevelSegments: 3,
    steps: 1,
    bevelSize: 0.5,
    bevelThickness: 0.4,
    curveSegments: 24,
  });
  geometry.computeBoundingBox();
  const box = geometry.boundingBox;
  const layout = AGENT_SHAPE_LAYOUT[key] ?? {};
  const scale = (layout.extent ?? 2.6) / Math.max(box.max.x - box.min.x, box.max.y - box.min.y);
  geometry.translate(-(box.min.x + box.max.x) / 2, -(box.min.y + box.max.y) / 2, -5);
  geometry.scale(scale * (layout.width ?? 1), -scale * (layout.height ?? 1), scale);
  geometry.translate(layout.x ?? 0, layout.y ?? 0, 0);
  geometry.computeVertexNormals();
  geometries.set(key, geometry);
  return geometry;
}
function grain(material) {
  material.onBeforeCompile = (shader) => {
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <dithering_fragment>",
      `#include <dithering_fragment>
      float first = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898,78.233))) * 43758.5453);
      float second = fract(sin(dot(gl_FragCoord.xy + vec2(31.7,9.2), vec2(39.346,11.135))) * 27463.235);
      float noise = .5 + (first + second - 1.) * .02;
      vec3 low = 2. * gl_FragColor.rgb * noise;
      vec3 high = 1. - 2. * (1. - gl_FragColor.rgb) * (1. - noise);
      gl_FragColor.rgb = mix(low, high, step(vec3(.5), gl_FragColor.rgb));`,
    );
  };
  return material;
}
export function createAgentAvatarRenderer(canvas) {
  clearTimeout(disposeTimer);
  if (!renderer) {
    renderer = new THREE.WebGLRenderer({
      alpha: true,
      antialias: true,
      preserveDrawingBuffer: true,
    });
    renderer.setSize(256, 256, false);
    renderer.setClearColor(0x000000, 0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
  }
  clients++;
  const context = canvas.getContext("2d"),
    scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1.5, 1.5, 1.5, -1.5, 0.1, 20);
  camera.position.set(0, 0, 6);
  const group = new THREE.Group();
  scene.add(group);
  const front = grain(
    new THREE.MeshBasicMaterial({
      color: 0xa4dfe0,
      side: THREE.DoubleSide,
    }),
  );
  const side = grain(
    new THREE.MeshBasicMaterial({
      color: 0x448f9a,
      side: THREE.DoubleSide,
    }),
  );
  const body = new THREE.Mesh(bodyGeometry("shield"), [front, side]);
  group.add(body);
  const face = new THREE.Group();
  group.add(face);
  face.position.set(0.131, 0.0665, 0);
  face.scale.setScalar(1.095);
  let expression, renderedColor, faceColor = "#111117";
  function setExpression(emotion) {
    if (emotion === expression) return;
    expression = emotion;
    for (const child of [...face.children]) {
      face.remove(child);
      child.geometry.dispose();
      child.material.dispose();
    }
    for (const [index, path] of agentFacePaths(emotion).entries()) {
      const data = new SVGLoader().parse(
        `<svg xmlns="http://www.w3.org/2000/svg"><path d="${path.d}"${path.transform ? ` transform="${path.transform}"` : ""}/></svg>`,
      );
      const shapes = data.paths.flatMap((p) => SVGLoader.createShapes(p));
      const geometry = new THREE.ShapeGeometry(shapes, 20);
      geometry.translate(-17.5, -17.5, 0);
      geometry.scale(0.0375, -0.0375, 0.0375);
      geometry.computeBoundingBox();
      const center = geometry.boundingBox.getCenter(new THREE.Vector3());
      geometry.translate(-center.x, -center.y, -center.z);
      const material = new THREE.MeshBasicMaterial({
        color: faceColor,
        side: THREE.DoubleSide,
        opacity: path.opacity ?? 1,
        transparent: path.opacity !== undefined,
      });
      const mesh = new THREE.Mesh(geometry, material);
      // Small picker marks have a larger optical size than dimensional marks.
      // Keep their shared layout spacing while scaling each feature around its centre.
      const pivot = new THREE.Vector3(-0.5 * 0.047, 0.5 * 0.047, 0);
      mesh.position.copy(center).multiplyScalar(0.047 / 0.0375)
        .sub(pivot).applyAxisAngle(new THREE.Vector3(0, 0, 1), 7 * Math.PI / 180).add(pivot);
      mesh.userData.blink = index < 2;
      face.add(mesh);
    }
  }
  group.rotation.set(0.180625, -0.328125, 0.095625);
  group.scale.setScalar(0.9875);
  let disposed = false, width = 0, pose;
  const sampleMotion = createAvatarMotion(Math.floor(Math.random() * 4294967296));
  function draw() {
    if (disposed || !context || !width) return false;
    if (pose) {
      const { lookX, lookY } = pose;
      group.position.y = pose.bob;
      group.rotation.set(-0.072 + lookY * 0.2, -0.25 + lookX * (lookX < 0 ? 0.3 : 0.85), pose.roll);
      face.position.x = 0.146 + lookX * (lookX < 0 ? 0.48 : 0.38);
      face.position.y = 0.1315 - lookY * 0.41;
      face.scale.setScalar(1.1 * (1 - 0.13 * Math.min(1.4, Math.hypot(lookX, lookY))));
    } else {
      group.position.y = 0;
      group.rotation.set(0.180625, -0.328125, 0.095625);
      face.position.x = 0.131;
      face.position.y = 0.0665;
      face.scale.setScalar(1.095);
    }
    for (const child of face.children) child.scale.y = child.userData.blink ? pose?.blink ?? 1 : 1;
    renderer.setViewport(0, 0, width, width);
    renderer.clear();
    renderer.render(scene, camera);
    context.clearRect(0, 0, width, width);
    context.drawImage(renderer.domElement, 0, 256 - width, width, width, 0, 0, width, width);
    return true;
  }
  const clock = subscribeAvatarFrames(elapsed => {
    pose = sampleMotion(elapsed);
    draw();
  });
  return {
    update({ color, shape, emotion = 0, silhouette = false }) {
      if (disposed || !context) return false;
      width = Math.max(0, Math.min(256, canvas.clientWidth));
      if (canvas.width !== width || canvas.height !== width) {
        canvas.width = width;
        canvas.height = width;
      }
      body.geometry = bodyGeometry(shape);
      face.position.z = body.geometry.boundingBox.max.z + 0.01;
      if (renderedColor !== color) {
        renderedColor = color;
        front.color.set(color);
        side.color.set(agentSideColor(color));
        faceColor = agentFaceColor(color);
        for (const child of face.children) child.material.color.set(faceColor);
      }
      setExpression(emotion);
      face.visible = !silhouette;
      clock.setEnabled(!silhouette && width > 0);
      if (silhouette) pose = undefined;
      else if (!clock.reduced && !pose) pose = sampleMotion(clock.elapsed);
      return draw();
    },
    setVisible(visible) { clock.setVisible(visible); },
    dispose() {
      if (disposed) return;
      disposed = true;
      clock.dispose();
      clients--;
      for (const child of face.children) {
        child.geometry.dispose();
        child.material.dispose();
      }
      front.dispose();
      side.dispose();

      if (!clients)
        disposeTimer = setTimeout(() => {
          if (clients) return;
          renderer?.dispose();
          renderer = undefined;
          for (const geometry of geometries.values()) geometry.dispose();
          geometries.clear();
        }, 0);
    },
  };
}

// @zeus-internal
/** Independently drawn outlines for the shared dimensional avatar. */
export const AGENT_SHAPE_PATHS = {
  shield:
    "M32 3C35 3 43 10 59 15Q62 16 61 21L60 38Q59 50 36 62Q32 64 28 62C7 51 4 45 4 35L3 20Q2 16 6 15C20 11 28 3 32 3Z",
  slender: "M32 5C47 4 55 11 54 26L52 44C51 57 43 62 31 61C17 61 10 54 10 42L10 24C10 11 18 5 32 5Z",
  pocket: "M13 9C7 9 4 13.5 4 22L5 44C5 53 10 56 18 56L47 56C56 56 60 52 60 44L60 20C60 12.5 56 8 48 8Z",
  petal:
    "M33 3C41 2 41 15 52 18C66 21 64 32 58 39C52 47 65 56 53 61C45 65 39 54 30 58C14 66 2 53 7 41C12 28 2 21 12 14C22 8 22 4 33 3Z",
  flower:
    "M31 5C40-2 47 6 45 15C60 6 66 21 55 30C69 37 59 52 49 48C52 64 36 68 30 54C20 68 7 59 13 47C-2 44 2 28 14 29C2 16 17 4 24 14Q25 7 31 5Z",
  star: "M32 3C37 3 39 16 42 19C45 23 60 19 62 25C65 31 51 37 49 41C47 45 54 58 49 61C43 65 36 53 31 53C26 52 16 65 11 60C6 56 14 46 13 41C12 36-2 30 2 24C6 18 19 23 23 19C27 15 27 3 32 3Z",
  heart: "M32 14C21-2 3 7 3 21C3 36 20 51 30 60Q32 62 35 60C47 49 62 36 62 21C62 7 44-2 32 14Z",
  cloud:
    "M14 52C6 52 1 47 1 40C1 29 7 24 14 24C11 14 20 7 27 12C28 2 46 4 46 21C54 15 63 24 61 34C67 44 59 52 49 52Z",
  diamond: "M30 3Q32 0 35 4L61 30Q64 33 61 36L35 62Q32 65 29 62L3 36Q0 33 3 30Z",
} as const;
/** Shared proportions for the dimensional shape surfaces. */
export const AGENT_SHAPE_LAYOUT: Partial<Record<keyof typeof AGENT_SHAPE_PATHS, {extent?:number;width?:number;height?:number;x?:number;y?:number}>> = {
 cloud:{extent:2.92,height:.94,x:-.04,y:.11},
 slender:{extent:2.56,width:1.06,x:.04},
 pocket:{y:-.04},
};
export type AgentShape = keyof typeof AGENT_SHAPE_PATHS | "robot" | "spark";
export const AGENT_SHAPES = [
  "slender",
  "pocket",
  "petal",
  "flower",
  "star",
  "heart",
  "cloud",
  "diamond",
  "shield",
] as const;
export const normalizeAgentShape = (shape: AgentShape) =>
  shape === "robot" ? "pocket" : shape === "spark" ? "star" : shape;
export const AGENT_EMOTIONS = [
  "Neutral",
  "Happy",
  "Angry",
  "Thinking",
  "Shook",
  "Curious",
  "Wink",
  "Sleepy",
  "Sad",
  "Worried",
  "Skeptical",
  "Focused",
  "Excited",
  "Calm",
  "Shy",
  "Confused",
] as const;

const capsule = (x: number, y: number, width: number, height: number) => {
  const r = Math.min(width, height) / 2;
  return `M${x + r} ${y}H${x + width - r}Q${x + width} ${y} ${x + width} ${y + r}V${y + height - r}Q${x + width} ${y + height} ${x + width - r} ${y + height}H${x + r}Q${x} ${y + height} ${x} ${y + height - r}V${y + r}Q${x} ${y} ${x + r} ${y}Z`;
};
/** Shared expression outlines; vector swatches and dimensional faces use the same features. */
export function agentFacePaths(emotion: number): { d: string; opacity?: number; transform?: string }[] {
  const eyes = (left = capsule(6, 11, 7.5, 16), right = capsule(19, 11, 7.5, 16)) => [{ d: left }, { d: right }];
  const brow = (d: string, opacity: number) => ({ d, opacity });
  const happyLeft = "M6 19C7 10 14 10 15 19L12 19Q10 14 9 19Z";
  const happyRight = "M19 21C20 12 27 12 28 21L25 21Q23 16 22 21Z";
  switch (emotion) {
    case 1:
      return eyes(happyLeft, happyRight);
    case 2:
      return [
        ...eyes(capsule(6, 14, 7.5, 8), capsule(19, 14.5, 7.5, 8)),
        brow("M6 6L17 10L16 12L5 8Z", .85),
        brow("M18 11L28 7L29 9L19 13Z", .85),
      ];
    case 3:
      return [
        ...eyes(capsule(6, 11.5, 7.5, 12), capsule(19, 16, 7.5, 8)),
        brow(capsule(8.5, 4.5, 10, 2), .765),
        brow("M20 8.7Q25 8.8 30 11.5L29.3 13Q25 10.7 20.2 10.7Z", .765),
      ];
    case 4:
      return [
        ...eyes(capsule(5.5, 7, 9, 22), capsule(18, 8.5, 9, 22)),
        brow(capsule(7, 3.5, 10, 2.5), .85),
        brow(capsule(19, 5, 10, 2.5), .85),
      ];
    case 5:
      return [
        ...eyes(capsule(6, 9, 8, 18), capsule(19, 13, 7.5, 12)),
        brow(capsule(5.5, 5, 10, 2), .68),
        brow(capsule(19, 7, 9, 2), .68),
      ];
    case 6:
      return eyes(capsule(6, 11, 8, 16), "M19 19Q23 16 27 19L26 22Q23 20 20 22Z");
    case 7:
      return eyes(capsule(6, 14, 9, 6), capsule(18, 18, 9, 5));
    case 8:
      return [
        ...eyes(capsule(6, 13, 7.5, 9), capsule(19, 14.5, 7.5, 9)),
        brow("M7 9.8L17 6L17.5 8L7.5 12Z", .72),
        brow("M21 6L29.5 11L28.5 13L20 8Z", .72),
      ];
    case 9:
      return [
        ...eyes(capsule(6, 11, 7.5, 16), capsule(19, 12, 7.5, 16)),
        brow("M7 8L10.5 3.5L14.5 7.5L13.5 9L10.5 6L8 10Z", .85),
        brow("M20 10L23.5 5.5L27.5 9.5L26.5 11L23.5 8L21 12Z", .85),
      ];
    case 10:
      return [
        ...eyes(capsule(6, 15.5, 9, 4), capsule(19, 14, 9, 11)),
        brow(capsule(6.5, 7.5, 12, 2.5), .68),
        brow(capsule(20, 8, 11, 2), .68),
      ];
    case 11:
      return [
        ...eyes(capsule(6, 14.5, 9, 6), capsule(18, 16, 9, 6)),
        brow("M6 7Q17 10 30 10L29.7 12Q17 12 5.7 9Z", .4),
      ];
    case 12:
      return [
        ...eyes("M5 19C6 8 15 8 16 19L12.8 19Q10.5 12.5 8.2 19Z", "M18.5 21C19.5 8 28.5 8 29 20L25.8 20Q23.5 13 21.2 20Z"),
        brow("M6 4Q18 5 30 7L29.7 9Q18 7 5.7 6Z", .62),
      ];
    case 13:
      return eyes(capsule(6, 15, 9, 4), capsule(19, 15.5, 9, 4));
    case 14:
      return eyes(capsule(7, 13, 6.5, 11), capsule(20, 13, 5.5, 11));
    case 15:
      return [
        { d: capsule(6, 12, 8, 8.5) },
        { d: capsule(19, 11.5, 8, 19), transform: "rotate(24 23 21)" },
        brow(capsule(8.5, 6.5, 10, 2), .765),
        brow("M19 7Q24 4 30 8L29.5 10Q24 7 19.5 9Z", .765),
      ];
    default:
      return eyes();
  }
}

"use client";
import { useEffect, useId, useRef, useState } from "react";
import { cx } from "@/lib/cx";
import { parseColor } from "react-aria-components";
import { createAgentAvatarRenderer } from "./agent-avatar-engine.jsx";
import { agentFaceColor } from "./agent-colors";
import {
  AGENT_SHAPE_PATHS,
  agentFacePaths,
  normalizeAgentShape,
  type AgentShape,
} from "./agent-avatar-paths";
export interface AgentAvatarProps {
  color?: string;
  shape?: AgentShape;
  emotion?: number;
  silhouette?: boolean;
  faceOnly?: boolean;
  className?: string;
}
/** One avatar surface for navigation, conversation labels and the appearance editor. */
export function AgentAvatar({
  color = "#a4dfe0",
  shape = "robot",
  emotion = 0,
  silhouette = false,
  faceOnly = false,
  className,
}: AgentAvatarProps) {
  const id = useId().replaceAll(":", "");
  const canvas = useRef<HTMLCanvasElement>(null);
  const configuration = useRef({ color, shape, emotion, silhouette });
  configuration.current = { color, shape, emotion, silhouette };
  const redraw = useRef<() => void>(() => {});
  const [ready, setReady] = useState(false);
  useEffect(() => {
    if (faceOnly || !canvas.current) { setReady(false);return; }
    let renderer: ReturnType<typeof createAgentAvatarRenderer> | undefined;
    let observer: ResizeObserver | undefined;
    let intersection: IntersectionObserver | undefined;
    let visibility: MutationObserver | undefined;
    let intersecting = true;
    const ancestors: HTMLElement[] = [];
    const element = canvas.current;
    const refreshVisibility = () => {
      let painted = true;
      if (typeof element.checkVisibility === "function") {
        painted = element.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true });
      } else {
        for (let node: HTMLElement | null = element; node; node = node.parentElement) {
          const style = getComputedStyle(node);
          if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0") {
            painted = false;break;
          }
        }
      }
      renderer?.setVisible(intersecting && painted);
    };
    const animationEnd = (event: Event) => {
      if (event.target === event.currentTarget) refreshVisibility();
    };
    const draw = () => {
      const current = configuration.current;
      try {
        element.style.color = current.color;
        refreshVisibility();
        setReady(renderer?.update({
          ...current,
          color: parseColor(getComputedStyle(element).color).toString("hex"),
        }) ?? false);
      } catch { setReady(false); }
    };
    try {
      renderer = createAgentAvatarRenderer(element);
      redraw.current = draw;
      draw();
      if (typeof ResizeObserver !== "undefined") {
        observer = new ResizeObserver(draw);
        observer.observe(element);
      }
      if (typeof IntersectionObserver !== "undefined") {
        intersection = new IntersectionObserver(entries => {
          for (const entry of entries) if (entry.target === element) {
            intersecting = entry.isIntersecting;
            refreshVisibility();
          }
        });
        intersection.observe(element);
      }
      visibility = new MutationObserver(() => {
        if (!configuration.current.silhouette) refreshVisibility();
      });
      for (let parent = element.parentElement; parent; parent = parent.parentElement) {
        ancestors.push(parent);
        visibility.observe(parent, { attributes: true, attributeFilter: ["class", "style", "hidden"] });
        parent.addEventListener("animationend", animationEnd);
        parent.addEventListener("transitionend", animationEnd);
      }
    } catch {
      setReady(false);
    }
    return () => {
      observer?.disconnect();
      intersection?.disconnect();
      visibility?.disconnect();
      for (const parent of ancestors) {
        parent.removeEventListener("animationend", animationEnd);
        parent.removeEventListener("transitionend", animationEnd);
      }
      if (redraw.current === draw) redraw.current = () => {};
      renderer?.dispose();
    };
  }, [faceOnly]);
  useEffect(() => redraw.current(), [color, shape, emotion, silhouette]);
  return (
    <span
      aria-hidden="true"
      className={cx("relative inline-block size-10 shrink-0 align-middle", className)}
    >
      <svg
        viewBox={faceOnly ? "0 0 34 34" : "0 0 68 68"}
        className={cx(
          "absolute inset-0 size-full overflow-visible",
          ready && !faceOnly && "invisible",
        )}
      >
        {!faceOnly && (
          <>
            <defs>
              <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
                <stop stopColor={color} />
                <stop offset="1" stopColor={color} stopOpacity=".85" />
              </linearGradient>
            </defs>
            <path
              d={AGENT_SHAPE_PATHS[normalizeAgentShape(shape)]}
              fill={color}
              transform="translate(2 0)"
              style={{ filter: "brightness(.65)" }}
            />
            <path d={AGENT_SHAPE_PATHS[normalizeAgentShape(shape)]} fill={`url(#${id})`} />
          </>
        )}
        {!silhouette && (
          <g
            transform={
              faceOnly ? "rotate(-7 17 17)" : "translate(14 14) rotate(-7 17 17) scale(1.1)"
            }
            fill={agentFaceColor(color)}
            stroke={agentFaceColor(color)}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {agentFacePaths(emotion).map((path, i) => (
              <path key={i} d={path.d} opacity={path.opacity} transform={path.transform} stroke="none" />
            ))}
          </g>
        )}
      </svg>
      {!faceOnly && (
        <canvas ref={canvas} className={cx("absolute inset-0 size-full", !ready && "invisible")} />
      )}
    </span>
  );
}

// @zeus-internal
import { parseColor } from "react-aria-components";

/** Independently fitted side tone from the rendered colour samples. */
export function agentSideColor(value: string): string {
  const color = parseColor(value).toFormat("hsl");
  return color
    .withChannelValue("hue", (color.getChannelValue("hue") + 5.5) % 360)
    .withChannelValue("saturation", color.getChannelValue("saturation") * 0.85)
    .withChannelValue("lightness", Math.max(0, color.getChannelValue("lightness") - 28))
    .toString("hex");
}

export function agentFaceColor(value: string): string {
  try {
    return parseColor(value).toFormat("hsl").getChannelValue("lightness") < 35
      ? "#fbfaf8"
      : "#111117";
  } catch {
    // CSS variables resolve on the canvas before its dimensional renderer draws.
    return "#111117";
  }
}

// @zeus-internal
interface Client {
  draw: (elapsed: number) => void;
  enabled: boolean;
  visible: boolean;
  elapsed: number;
}
const clients = new Set<Client>();
let frame = 0, previous: number | undefined, lastPaint: number | undefined;
let reduced: MediaQueryList | undefined;
const runnable = () => !reduced?.matches && !document.hidden && [...clients].some(c => c.enabled && c.visible);
function synchronize() {
  if (!runnable()) {
    if (frame) cancelAnimationFrame(frame);
    frame = 0;previous = undefined;lastPaint = undefined;
  } else if (!frame) frame = requestAnimationFrame(tick);
}
function tick(now: number) {
  frame = 0;
  if (!runnable()) { synchronize();return; }
  if (lastPaint === undefined || now - lastPaint >= 1000 / 30 - 0.5) {
    const delta = previous === undefined ? 0 : Math.max(0, now - previous);
    previous = now;
    lastPaint = now;
    for (const client of clients) if (client.enabled && client.visible) {
      client.elapsed += delta;
      client.draw(client.elapsed);
    }
  }
  synchronize();
}

/** A single paced RAF and preference subscription serve all dimensional avatars. */
export function subscribeAvatarFrames(draw: (elapsed: number) => void) {
  if (!clients.size) {
    reduced = matchMedia("(prefers-reduced-motion: reduce)");
    reduced.addEventListener("change", synchronize);
    document.addEventListener("visibilitychange", synchronize);
  }
  const client: Client = { draw, enabled: false, visible: true, elapsed: 0 };
  clients.add(client);
  let disposed = false;
  return {
    get elapsed() { return client.elapsed; },
    get reduced() { return reduced?.matches ?? false; },
    setEnabled(enabled: boolean) { if (!disposed) { client.enabled = enabled;synchronize(); } },
    setVisible(visible: boolean) { if (!disposed) { client.visible = visible;synchronize(); } },
    dispose() {
      if (disposed) return;
      disposed = true;clients.delete(client);synchronize();
      if (!clients.size) {
        reduced?.removeEventListener("change", synchronize);
        document.removeEventListener("visibilitychange", synchronize);
        reduced = undefined;
      }
    },
  };
}

// @zeus-internal
export interface AvatarMotionFrame {
  lookX: number;
  lookY: number;
  blink: number;
  bob: number;
  roll: number;
}
const targets = [
  [-24, -19], [-1, -5], [-4, -13], [6, -11], [2, -4], [12, -16],
  [14, 15], [-4, 11], [-4, 16], [-6, 12], [-14, 9], [16, -23],
  [11, -17], [3, 0], [-2, 4], [7, 1],
] as const;
const gazeIntervals = [2000, 2500, 1000, 2700, 1800, 1400, 1100, 1500, 900, 1700, 1300];
const blinkIntervals = [2283, 2383, 4050, 5166, 6633, 7016, 7399];
const blinkDurations = [110, 142, 164, 188, 194, 198];
const random = (seed: number) => () => {
  seed |= 0;
  seed = seed + 0x6d2b79f5 | 0;
  let value = Math.imul(seed ^ seed >>> 15, 1 | seed);
  value ^= value + Math.imul(value ^ value >>> 7, 61 | value);
  return ((value ^ value >>> 14) >>> 0) / 4294967296;
};
const smootherstep = (value: number) => {
  const t = Math.max(0, Math.min(1, value));
  return t * t * t * (t * (6 * t - 15) + 10);
};

/** Independent idle motion calibrated from rendered timing and pose samples. */
export function createAvatarMotion(seed: number) {
  let gazeRandom = random(seed ^ 0x21f0aaad), blinkRandom = random(seed ^ 0x735a2d97);
  const phase = random(seed ^ 0x4ac1709b)() * Math.PI * 2;
  let previous = -1, gazeStart = 0, nextGaze = 0, targetIndex = -1;
  let from = [0, 0], to = [0, 0];
  let blinkStart = 0, blinkDuration = 0;
  const pick = (values: readonly number[], next: () => number) => values[Math.floor(next() * values.length)];
  const reset = () => {
    gazeRandom = random(seed ^ 0x21f0aaad);
    blinkRandom = random(seed ^ 0x735a2d97);
    previous = -1;gazeStart = 0;targetIndex = -1;from = [0, 0];to = [0, 0];
    nextGaze = pick(gazeIntervals, gazeRandom);
    blinkStart = pick(blinkIntervals, blinkRandom);
    blinkDuration = pick(blinkDurations, blinkRandom);
  };
  reset();
  return (elapsed: number): AvatarMotionFrame => {
    const time = Math.max(0, elapsed);
    if (time < previous) reset();
    previous = time;
    while (time >= nextGaze) {
      from = [...to];
      const index = Math.floor(gazeRandom() * targets.length);
      targetIndex = index === targetIndex ? (index + 1) % targets.length : index;
      const target = targets[targetIndex];
      to = [(target[0] + 3) / 30, (target[1] + 9) / 25];
      gazeStart = nextGaze;
      nextGaze += pick(gazeIntervals, gazeRandom);
    }
    while (time >= blinkStart + blinkDuration) {
      blinkStart += pick(blinkIntervals, blinkRandom);
      blinkDuration = pick(blinkDurations, blinkRandom);
    }
    const progress = smootherstep((time - gazeStart) / 895);
    const blinkProgress = (time - blinkStart) / blinkDuration;
    const wave = Math.sin(time / 8015 * Math.PI * 2 + phase);
    return {
      lookX: from[0] + (to[0] - from[0]) * progress,
      lookY: from[1] + (to[1] - from[1]) * progress,
      blink: blinkProgress < 0 || blinkProgress > 1 ? 1 : Math.max(0.1, 1 - Math.sin(Math.PI * blinkProgress) ** 1.3),
      bob: wave * 0.01508,
      roll: 0.055 + wave * 0.028,
    };
  };
}

// @zeus-internal
"use client";
import { useEffect, useState } from "react";
import type { SettingsMarketplaceProps } from "./settings-marketplace";
import { DEFAULT_MARKETPLACE_ITEMS } from "./marketplace-data";
export function useMarketplaceInstallation({
  items = DEFAULT_MARKETPLACE_ITEMS,
  installedIds,
  onInstalledChange,
  storageKey = "zeus:marketplace:v1",
}: Omit<SettingsMarketplaceProps, "onClose"> = {}) {
  const [local, setLocal] = useState(() =>
    items.filter((item) => item.installed).map((item) => item.id),
  );
  const controlled = installedIds !== undefined;
  useEffect(() => {
    if (controlled || !storageKey) return;
    const read = () => {
      try {
        const raw = localStorage.getItem(storageKey);
        if (!raw) return;
        const ids: unknown = JSON.parse(raw);
        if (Array.isArray(ids) && ids.every((id) => typeof id === "string")) setLocal(ids);
      } catch {}
    };
    read();
    window.addEventListener("storage", read);
    window.addEventListener("zeus-marketplace-change", read);
    return () => {
      window.removeEventListener("storage", read);
      window.removeEventListener("zeus-marketplace-change", read);
    };
  }, [controlled, storageKey]);
  return {
    installed: installedIds ?? local,
    change: (ids: string[]) => {
      if (!controlled) {
        setLocal(ids);
        if (storageKey)
          try {
            localStorage.setItem(storageKey, JSON.stringify(ids));
            window.dispatchEvent(new Event("zeus-marketplace-change"));
          } catch {}
      }
      onInstalledChange?.(ids);
    },
  };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { cx } from "@/lib/cx";

/**
 * The "Current plan" artwork (settings-plan-art.png) rendered through a WebGL
 * fragment shader as a burning, wind-torn flag:
 *
 *   wave   the image UVs ripple with two crossed sine waves plus low-freq
 *          fbm turbulence, amplitude growing toward the edges — center stays
 *          pinned like a flag on a pole, edges flap.
 *   burn   a slow-drifting fbm field is thresholded against an edge-weighted,
 *          breathing burn level: past the threshold the cloth is gone (alpha
 *          holes), just before it a hot ember rim glows orange→yellow, and
 *          just inside that the fabric chars dark.
 *   sparks tiny embers detach from burning regions and drift up-right,
 *          flickering out.
 *
 * Same raw-WebGL recipe as the effort slider's FlameOverlay (ai-chat-menus):
 * fullscreen quad, rAF loop, and a plain <img> fallback when a context can't
 * be created. The radial fade into the card bg stays as a DOM overlay above.
 */

const VERT = /* glsl */ `
attribute vec2 a_pos;
varying vec2 v_uv;
void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`;

const FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D u_tex;
uniform float u_time;
uniform vec2 u_mouse;      // pointer in UV space (y up)
uniform float u_mouseStr;  // 0..1, eased in JS
varying vec2 v_uv;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p = p * 2.03 + vec2(17.0, 9.2);
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = v_uv;

  // 0 at the center, 1 at the corners — drives both flap amplitude and burn.
  float edge = clamp(distance(uv, vec2(0.5)) * 1.6, 0.0, 1.0);

  // Pointer heat: a soft hotspot under the cursor that stokes the burn and
  // agitates the cloth around it.
  float mouseBoost = u_mouseStr * smoothstep(0.2, 0.02, distance(v_uv, u_mouse));

  // Flag-in-wind: crossed sines + a pinch of turbulence, pinned at center.
  float amp = 0.004 + 0.022 * edge * edge + 0.012 * mouseBoost;
  uv.x += sin(uv.y * 9.0 + u_time * 2.2) * amp;
  uv.y += sin(uv.x * 12.0 - u_time * 2.7) * amp * 0.85;
  uv += (vec2(
    fbm(v_uv * 3.0 + vec2(u_time * 0.35, 0.0)),
    fbm(v_uv * 3.0 + vec2(0.0, u_time * 0.31) + 31.7)
  ) - 0.5) * 0.03 * edge;

  vec4 img = texture2D(u_tex, uv);

  // Burn field: drifting noise vs an edge-weighted, breathing threshold —
  // the pointer hotspot raises the local burn level on top.
  float n = fbm(uv * 4.5 + vec2(u_time * 0.3, -u_time * 0.48));
  float breathe = 0.78 + 0.22 * sin(u_time * 1.1 + n * 7.0);
  float burn = min(edge * breathe * 0.85 + mouseBoost * 0.45, 1.05);
  float d = n - (1.0 - burn); // > 0 → consumed

  float hole = smoothstep(0.0, 0.07, d);
  float rim = smoothstep(-0.11, 0.0, d) * (1.0 - hole);
  float charr = smoothstep(-0.26, -0.08, d) * (1.0 - rim) * (1.0 - hole);

  // Ember rim: deep orange at the outside, white-yellow right at the tear.
  float hot = smoothstep(-0.05, 0.0, d);
  vec3 ember = mix(vec3(1.0, 0.38, 0.08), vec3(1.0, 0.85, 0.35), hot);

  vec3 col = img.rgb;
  col = mix(col, col * vec3(0.32, 0.24, 0.22), charr * 0.75); // char darkening
  col = mix(col, ember, rim);
  col += ember * rim * 0.6; // rim over-glow

  float alpha = img.a * (1.0 - hole);

  // Burning paper flakes: three parallax layers of small rotated slivers
  // that drift up-right while tumbling. Each has its own life cycle —
  // ignites bright yellow-white, cools to orange, then dies out — and they
  // only spawn near burning fabric (or under the pointer's hotspot).
  float gate = smoothstep(0.12, 0.5, edge * breathe) + mouseBoost;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float scale = 13.0 + fi * 8.0;
    vec2 sp = v_uv * scale + vec2(-u_time * (0.8 + fi * 0.5), -u_time * (2.0 + fi * 1.1));
    vec2 cell = floor(sp);
    float sh = hash(cell + fi * 13.7);
    if (sh > 0.7) {
      vec2 pos = 0.2 + 0.6 * vec2(hash(cell + 3.1), hash(cell + 7.7));
      // Tumbling sway while it floats
      pos.x += sin(u_time * (2.0 + sh * 3.0) + sh * 20.0) * 0.08;
      vec2 delta = fract(sp) - pos;
      // Rotated, elongated sliver — reads as a torn paper fragment.
      float angle = sh * 6.2831 + u_time * (1.2 + sh * 2.0);
      vec2 r = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * delta;
      float body = smoothstep(0.17, 0.03, length(r * vec2(1.0, 2.6)));
      // Life cycle: quick ignite → glow → burn out and vanish.
      float life = fract(u_time * (0.35 + sh * 0.5) + sh * 11.0);
      float glow = smoothstep(0.0, 0.1, life) * (1.0 - smoothstep(0.5, 0.95, life));
      float flicker = 0.75 + 0.25 * sin(u_time * 11.0 + sh * 40.0);
      vec3 flakeCol = mix(vec3(1.0, 0.4, 0.07), vec3(1.0, 0.93, 0.55), glow * flicker);
      float lum = body * glow * flicker * min(gate, 1.2);
      col += flakeCol * lum;
      alpha = max(alpha, lum * 0.95);
    }
  }

  gl_FragColor = vec4(col, alpha);
}
`;

/**
 * Paints the built-in artwork — the three token-coloured blobs — into an
 * offscreen canvas so the shader has something to burn when no `src` is given.
 *
 * Exists so the component animates on its own: a CLI install ships no image,
 * and a static gradient in place of the flame made the packaged component look
 * like a different thing from the one in the templates. Colours are read from
 * the live custom properties rather than hardcoded, so it follows the theme.
 */
function paintFallbackArt(size: number): HTMLCanvasElement | null {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  if (!ctx) return null;

  const styles = getComputedStyle(document.documentElement);
  const token = (name: string, fallback: string) =>
    styles.getPropertyValue(name).trim() || fallback;

  // Soft-edged discs, matching the DOM fallback's positions and 70% alpha.
  // A radial gradient rather than ctx.filter = blur(): Safari leaves the
  // filter unimplemented on some versions, and a hard disc would read as a
  // pasted circle instead of a glow.
  const blob = (cx: number, cy: number, r: number, color: string) => {
    const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
    gradient.addColorStop(0, color);
    gradient.addColorStop(0.55, color);
    gradient.addColorStop(1, "transparent");
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();
  };

  ctx.fillStyle = token("--color-background-tertiary-default", "#ebebeb");
  ctx.fillRect(0, 0, size, size);
  ctx.globalAlpha = 0.7;
  blob(size * 0.125, size * 0.125, size * 0.42, token("--color-blue-400", "#3392ff"));
  blob(size * 0.83, size * 0.58, size * 0.38, token("--color-lime-400", "#9ae600"));
  blob(size * 0.5, size * 0.95, size * 0.42, token("--color-orange-400", "#ff8904"));
  ctx.globalAlpha = 1;

  return canvas;
}

export function PlanArtFlame({ src, className }: { src?: string; className?: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const gl = canvas.getContext("webgl", { alpha: true, premultipliedAlpha: false });
    if (!gl) {
      setFailed(true);
      return;
    }

    const { width, height } = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    gl.viewport(0, 0, canvas.width, canvas.height);

    const compile = (type: number, source: string) => {
      const shader = gl.createShader(type)!;
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      return shader;
    };
    const program = gl.createProgram()!;
    gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT));
    gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG));
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      setFailed(true);
      return;
    }
    gl.useProgram(program);

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    const aPos = gl.getAttribLocation(program, "a_pos");
    gl.enableVertexAttribArray(aPos);
    gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

    const uTime = gl.getUniformLocation(program, "u_time");
    const uMouse = gl.getUniformLocation(program, "u_mouse");
    const uMouseStr = gl.getUniformLocation(program, "u_mouseStr");
    gl.uniform1i(gl.getUniformLocation(program, "u_tex"), 0);

    // Pointer tracked on window (overlays sit above the canvas, so listening
    // on the canvas itself would never fire); eased per-frame in the loop.
    const target = { x: 0.5, y: 0.5, str: 0 };
    const eased = { x: 0.5, y: 0.5, str: 0 };
    const onPointerMove = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      const x = (event.clientX - rect.left) / rect.width;
      const y = 1 - (event.clientY - rect.top) / rect.height; // GL y-up
      const inside = x > -0.15 && x < 1.15 && y > -0.15 && y < 1.15;
      if (inside) {
        target.x = x;
        target.y = y;
      }
      target.str = inside ? 1 : 0;
    };
    window.addEventListener("pointermove", onPointerMove);

    // NPOT-safe texture params (no mipmaps, clamp, linear).
    const texture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);

    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);

    let raf = 0;
    let disposed = false;
    const start = performance.now();
    const draw = (now: number) => {
      gl.uniform1f(uTime, (now - start) / 1000);
      // Ease the pointer hotspot so the heat trails the cursor smoothly.
      eased.x += (target.x - eased.x) * 0.12;
      eased.y += (target.y - eased.y) * 0.12;
      eased.str += (target.str - eased.str) * 0.07;
      gl.uniform2f(uMouse, eased.x, eased.y);
      gl.uniform1f(uMouseStr, eased.str);
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      raf = requestAnimationFrame(draw);
    };

    const upload = (source: TexImageSource) => {
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
      raf = requestAnimationFrame(draw);
    };

    if (src) {
      const image = new Image();
      image.onload = () => {
        if (disposed) return;
        upload(image);
      };
      image.onerror = () => setFailed(true);
      image.src = src;
    } else {
      // No artwork supplied: burn the built-in blobs instead of falling back
      // to a static gradient.
      const art = paintFallbackArt(512);
      if (!art) {
        setFailed(true);
        return;
      }
      upload(art);
    }

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onPointerMove);
    };
  }, [src]);

  // Only when WebGL itself is unavailable: with no `src` the shader now runs
  // on generated artwork, so this is the no-context / broken-image path.
  if (failed) {
    return (
      <div
        aria-hidden
        className={cx(
          "relative overflow-hidden bg-background-tertiary-default",
          className,
        )}
      >
        <span className="absolute -top-1/4 -left-1/4 size-3/4 rounded-full bg-blue-400/70 blur-2xl" />
        <span className="absolute top-1/4 right-0 size-2/3 rounded-full bg-lime-400/70 blur-2xl" />
        <span className="absolute right-1/4 -bottom-1/4 size-3/4 rounded-full bg-orange-400/70 blur-2xl" />
      </div>
    );
  }
  return <canvas ref={canvasRef} className={className} aria-hidden />;
}

"use client";
