import { Button, ButtonLink } from "../../base/buttons/button";
import { Input } from "../../base/input/input";
import { PillTab, PillTabList } from "../../base/tabs/pill-tab";
import { CardSurface, cardSurfaceClasses } from "../charts/card-surface";
import { AgentAvatar, type AgentAvatarProps } from "../agent-creator/agent-avatar";
import { SettingsPageHeader } from "./settings-page-header";
import { useMarketplaceInstallation } from "./marketplace-installation";
import { DEFAULT_MARKETPLACE_ITEMS } from "./marketplace-data";
export interface MarketplaceItem {
  id: string;
  kind: "bot" | "plugin";
  name: string;
  category: string;
  description: string;
  detail?: string;
  color?: string;
  shape?: AgentAvatarProps["shape"];
  icon?: ReactNode;
  installed?: boolean;
  website?: string;
  skill?: { name: string; description: string };
}
export interface SettingsMarketplaceProps {
  onClose: () => void;
  items?: readonly MarketplaceItem[];
  installedIds?: readonly string[];
  /** Browser-local demo installation state; null disables persistence. */
  storageKey?: string | null;
  onInstalledChange?: (ids: string[]) => void;
}
type Category = "Discover" | "Plugins" | "Bots" | "Installed";
/** Searchable workspace extensions and agent cards, with host-owned installation callbacks. */
export function SettingsMarketplace({
  onClose,
  items = DEFAULT_MARKETPLACE_ITEMS,
  installedIds,
  onInstalledChange,
  storageKey,
}: SettingsMarketplaceProps) {
  const [category, setCategory] = useState<Category>("Discover"),
    [query, setQuery] = useState(""),
    [selectedId, setSelectedId] = useState<string | null>(null);
  const { installed, change } = useMarketplaceInstallation({
    items,
    installedIds,
    onInstalledChange,
    storageKey,
  });
  const [copied, setCopied] = useState(false);
  const selected = items.find((i) => i.id === selectedId);
  const scroll = useRef<HTMLDivElement>(null);
  const changeCategory = (next: Category) => {
    setCategory(next);
    setSelectedId(null);
    if (scroll.current) scroll.current.scrollTop = 0;
  };
  const install = (item: MarketplaceItem) => {
    const next = installed.includes(item.id)
      ? installed.filter((id) => id !== item.id)
      : [...installed, item.id];
    change(next);
  };
  const open = (item: MarketplaceItem) => {
    setSelectedId(item.id);
    setCopied(false);
    if (scroll.current) scroll.current.scrollTop = 0;
  };
  const filtered = items.filter((i) =>
    `${i.name} ${i.category} ${i.description}`.toLowerCase().includes(query.toLowerCase().trim()),
  );
  const bots = filtered.filter((i) => i.kind === "bot"),
    plugins = filtered.filter((i) => i.kind === "plugin");
  const addButton = (item: MarketplaceItem, primary = false) => (
    <Button
      size={primary ? "medium" : "small"}
      variant={primary && !installed.includes(item.id) ? "primary" : "secondary"}
      className="mt-auto w-full shrink-0 rounded-full"
      aria-label={`${installed.includes(item.id) ? (primary ? "Remove" : "View added") : "Add"} ${item.name}`}
      onClick={() => (installed.includes(item.id) && !primary ? open(item) : install(item))}
    >
      {installed.includes(item.id) ? (primary ? "Remove" : "Added") : "Add"}
    </Button>
  );
  const grid = (entries: MarketplaceItem[]) => (
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
      {entries.map((item) => (
        <MarketplaceCard key={item.id} item={item} onOpen={() => open(item)}>
          {addButton(item)}
        </MarketplaceCard>
      ))}
    </div>
  );
  return (
    <>
      <SettingsPageHeader
        title="Marketplace"
        roundClose
        onClose={onClose}
        onBack={selected ? () => setSelectedId(null) : undefined}
        className="px-4 pb-4 sm:px-8"
      />
      {!selected && (
        <div className="flex shrink-0 flex-col gap-3 px-4 pb-4 sm:px-8">
          <Input
            aria-label="Search marketplace"
            placeholder="Find your next tool or teammate"
            leadingIcon={RiSearchLine}
            value={query}
            onChange={setQuery}
            fieldClassName="rounded-xl bg-background-secondary-default shadow-none"
          />
          <PillTabList aria-label="Marketplace categories" className="w-fit max-w-full flex-wrap">
            {(["Discover", "Plugins", "Bots", "Installed"] as const).map((tab) => (
              <PillTab
                key={tab}
                variant="gray"
                isSelected={category === tab}
                onSelect={() => changeCategory(tab)}
              >
                {tab}
              </PillTab>
            ))}
          </PillTabList>
        </div>
      )}
      <div className="relative min-h-0 flex-1">
