"use client";

import { useEffect, useRef, useState, type ComponentType } from "react";
import {
  RiBankCardLine,
  RiBookOpenLine,
  RiCheckboxCircleFill,
  RiCodeBlock,
  RiDatabase2Line,
  RiGitMergeLine,
  RiOrganizationChart,
  RiPaletteLine,
  RiPlugLine,
  RiSchoolLine,
  RiStore2Line,
  RiSettings6Line,
  RiSettingsLine,
  RiToolsFill,
} from "@remixicon/react";
import { cx } from "@/lib/cx";
import { DialogLayer } from "../../base/dialog/dialog-layer";
import { useMarketplaceInstallation } from "./marketplace-installation";
import { SettingsPageHeader } from "./settings-page-header";
import { SettingsMarketplace, type SettingsMarketplaceProps } from "./settings-marketplace";
import { MenuGroup, MenuItemButton } from "../../base/dropdown/menu-parts";
import { SettingsGeneral } from "./settings-general";
import { SettingsProfile, type SettingsProfileDefaults } from "./settings-profile";
import { SettingsStorage } from "./settings-storage";
import { SettingsTools } from "./settings-tools";

/**
 * The app-wide settings modal, opened from any sidebar's "Settings" item.
 *
 * The shared dialog layer owns portal, dismissal and presence. The rail is
 * 56px on mobile, 192px at the middle breakpoint and 240px on desktop.
 * The fixed title row and scrollable page retain 32px horizontal insets.
 */

export type SettingsPage = "general" | "profile" | "storage" | "tools" | "marketplace";

export interface SettingsModalProps {
  /** Controlled open state, owned by the host page, sidebar, or menu. */
  isOpen: boolean;
  /** Called by the backdrop, close button, and Escape key. */
  onClose: () => void;
  /** Page selected each time the modal opens. */
  defaultPage?: SettingsPage;
  /** Optional product artwork used by the animated Current plan card. */
  planArtSrc?: string;
  /** Product name used by account, destination and notification labels. */
  appName?: string;
  /** Initial identity fields for the editable profile page. */
  profileDefaults?: SettingsProfileDefaults;
  /** Optional names for the tools page's project scope presets. */
  scopeLabels?: readonly string[];
  marketplace?: Omit<SettingsMarketplaceProps, "onClose">;
  /** Include workspace discovery in the settings rail. */
  enableMarketplace?: boolean;
}

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

interface NavEntry {
  label: string;
  icon: IconComponent;
  /** Only pages that exist are navigable; the rest render as static rows. */
  page?: SettingsPage;
}

const NAV_GROUPS: { label: string; items: NavEntry[] }[] = [
  {
    label: "Settings",
    items: [
      { label: "General", icon: RiSettings6Line, page: "general" },
      { label: "Profile", icon: RiSchoolLine, page: "profile" },
      { label: "Marketplace", icon: RiStore2Line, page: "marketplace" },
      { label: "Appearance", icon: RiPaletteLine },
      { label: "Billing", icon: RiBankCardLine },
      { label: "Rules and Workflows", icon: RiOrganizationChart },
      { label: "Tools", icon: RiToolsFill, page: "tools" },
      { label: "Storage", icon: RiDatabase2Line, page: "storage" },
    ],
  },
  {
    label: "Desktop app",
    items: [
      { label: "General", icon: RiSettingsLine },
      { label: "Plugins", icon: RiPlugLine },
      { label: "Developer", icon: RiCodeBlock },
    ],
  },
  {
    label: "Customize",
    items: [
      { label: "Skills", icon: RiBookOpenLine },
      { label: "Git", icon: RiGitMergeLine },
    ],
  },
];

const PAGE_TITLES: Record<SettingsPage, string> = {
  general: "General",
  profile: "Profile",
  storage: "Storage",
  tools: "Tools",
  marketplace: "Marketplace",
};

export function SettingsModal({
  isOpen,
  onClose,
  defaultPage = "general",
  planArtSrc,
  appName = "Zeus",
  profileDefaults,
  scopeLabels,
  marketplace,
  enableMarketplace = defaultPage === "marketplace" || marketplace !== undefined,
}: SettingsModalProps) {
  const [page, setPage] = useState<SettingsPage>(defaultPage);
  const marketplaceState = useMarketplaceInstallation(marketplace);

  // "Saved" toast — floats half-out of the panel's bottom edge for ~2s
  // whenever a profile field commits a change (Enter / blur). Three phases
  // so the motion is directional: it rises in from below ("hidden" starting
  // offset) and keeps drifting upward while fading out ("leaving" offset).
  const [savedPhase, setSavedPhase] = useState<"hidden" | "shown" | "leaving">("hidden");
  const savedTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const showSavedToast = () => {
    if (savedTimer.current) clearTimeout(savedTimer.current);
    setSavedPhase("shown");
    savedTimer.current = setTimeout(() => {
      setSavedPhase("leaving");
      // Reset to the below-the-edge start once the fade-out finished, so the
      // next save rises in from the bottom again (invisible: opacity 0 → 0).
      savedTimer.current = setTimeout(() => setSavedPhase("hidden"), 220);
    }, 2000);
  };

  // Top fade over the scrolling page so rows dissolve under the title row
  // instead of cutting sharply (same recipe as the medical alerts feed).
  const [contentScrolled, setContentScrolled] = useState(false);

  useEffect(() => {
    if (isOpen) setPage(defaultPage);
    else setSavedPhase("hidden");
    return () => {
      if (savedTimer.current) clearTimeout(savedTimer.current);
    };
    // The default page is applied when opening, preserving the active page while open.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);

  return (
    <DialogLayer
      isOpen={isOpen}
      onClose={onClose}
      label="Settings"
      className="flex h-[614px] max-h-[calc(100dvh-32px)] w-[871px] max-w-[calc(100vw-32px)]"
      floatingContent={
        <div
          aria-live="polite"
          className={cx(
            "pointer-events-none absolute bottom-0 left-1/2 z-10 flex -translate-x-1/2 items-center gap-1",
            "rounded-full border border-border-button-default bg-background-primary-default py-1 pr-2.5 pl-1.5 shadow-dropdown",
            "transition-[opacity,transform,filter] duration-200 ease-out",
            savedPhase === "shown" && "translate-y-1/2 opacity-100 scale-100 blur-0",
            // Starts below the resting spot, rises in; keeps drifting up on exit.
            savedPhase === "hidden" && "translate-y-[calc(50%+12px)] opacity-0 scale-90 blur-[2px]",
            savedPhase === "leaving" &&
              "translate-y-[calc(50%-10px)] opacity-0 scale-90 blur-[2px]",
          )}
        >
          <RiCheckboxCircleFill className="size-4 shrink-0 text-lime-600" aria-hidden />
          <span className="text-body-2-medium whitespace-nowrap text-text-primary">Saved</span>
        </div>
      }
    >
      {/* The rail composes the same group and row primitives as menus. */}
      <nav
        aria-label="Settings sections"
        className="flex w-14 shrink-0 flex-col gap-5 overflow-y-auto border-e border-separator-border bg-background-secondary-default p-2.5 sm:w-48 lg:w-60"
      >
        {NAV_GROUPS.map((group) => (
          <MenuGroup key={group.label} label={group.label} labelClassName="hidden sm:block">
            {group.items
              .filter((item) => item.page !== "marketplace" || enableMarketplace)
              .map((item) => {
                const selected = item.page !== undefined && item.page === page;
                return (
                  <MenuItemButton
                    key={`${group.label}:${item.label}`}
                    variant="navigation"
                    active={selected}
                    aria-label={item.label}
                    title={item.label}
                    aria-current={selected ? "page" : undefined}
                    onClick={
                      item.page
                        ? () => {
                            setPage(item.page!);
                            setContentScrolled(false);
                          }
                        : undefined
                    }
                  >
                    <item.icon
                      className="size-5 shrink-0 text-foreground-icon-secondary"
                      aria-hidden
                    />
                    <span
                      className={cx(
                        "hidden truncate text-body-medium sm:block",
                        selected ? "text-text-primary" : "text-text-secondary",
                      )}
                    >
                      {item.label}
                    </span>
                  </MenuItemButton>
                );
              })}
          </MenuGroup>
        ))}
      </nav>

      {/* Content pane — fixed title row, scrollable page below */}
      <div className="flex min-w-0 flex-1 flex-col">
        {page === "marketplace" ? (
          <SettingsMarketplace
            {...marketplace}
            installedIds={marketplaceState.installed}
            onInstalledChange={marketplaceState.change}
            onClose={onClose}
          />
        ) : (
          <>
            <SettingsPageHeader
              title={PAGE_TITLES[page]}
              onClose={onClose}
              className={page === "storage" ? "pb-1.5" : undefined}
            />
            <div className="relative min-h-0 flex-1">
              <div
                className="h-full overflow-y-auto px-8 pb-8"
                onScroll={(e) => setContentScrolled(e.currentTarget.scrollTop > 0)}
              >
                {page === "profile" ? (
                  <SettingsProfile
                    onSaved={showSavedToast}
                    appName={appName}
                    defaults={profileDefaults}
                  />
                ) : page === "storage" ? (
                  <SettingsStorage />
                ) : page === "tools" ? (
                  <SettingsTools appName={appName} scopeLabels={scopeLabels} />
                ) : (
                  <SettingsGeneral planArtSrc={planArtSrc} appName={appName} />
                )}
              </div>
              {/* Progressive top fade — eases in once the page is scrolled so
                content dissolves under the title row instead of hard-cutting. */}
              <div
                aria-hidden
                className={cx(
                  "pointer-events-none absolute inset-x-0 top-0 h-10 bg-linear-to-b from-background-primary-default to-transparent",
                  "transition-opacity duration-200 ease-out",
                  contentScrolled ? "opacity-100" : "opacity-0",
                )}
              />
            </div>
          </>
        )}
      </div>
    </DialogLayer>
  );
}

